sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, imarcuryemplate) {
    if (newValue === '') {
        return;
    }

    var limarcury = g_form.getValue('u_handle');
    g_form.clearOptions('u_handle');

    if (newValue == '1') {
        g_form.addOption('u_handle', '1', 'approval1');
        g_form.addOption('u_handle', '2', 'approval2');
        g_form.addOption('u_handle', '3', 'approval3');
    }

    if (newValue == '2') {
        g_form.addOption('u_handle', '4', 'acres1');
        g_form.addOption('u_handle', '5', 'acres2');
        g_form.addOption('u_handle', '6', 'acres3');
    }

    if (newValue == '3') {
        g_form.addOption('u_handle', '7', 'marcury1');
        g_form.addOption('u_handle', '8', 'marcury2');
        g_form.addOption('u_handle', '9', 'marcury3');
    }

    if (isLoading && !g_form.isNewRecord()) {
        g_form.setValue('u_handle', limarcury);
    }
}
